// final class ListNode { var val: Int; var next: ListNode?; init(_ v: Int, _ n: ListNode? = nil) { val = v; next = n } }
func addTwoNumbers(_ l1: ListNode?, _ l2: ListNode?) -> ListNode? {
    let dummy = ListNode(0)
    var tail = dummy, a = l1, b = l2, carry = 0
    while a != nil || b != nil || carry > 0 {
        let sum = (a?.val ?? 0) + (b?.val ?? 0) + carry
        carry = sum / 10
        tail.next = ListNode(sum % 10)
        tail = tail.next!
        a = a?.next; b = b?.next
    }
    return dummy.next
}
